import type { Register, SessionUsage } from 'claude-code'

const STALE_PANE = 'context-bar'
const FREE_COLOR = '#2b2d3a'
const POLL_MS = 2500

const PALETTE: [string, string][] = [
  ['system prompt', '#7aa2f7'],
  ['system tools', '#bb9af7'],
  ['mcp tools', '#e0af68'],
  ['mcp server instructions', '#c3e88d'],
  ['custom agents', '#f7768e'],
  ['memory files', '#9ece6a'],
  ['skills', '#73daca'],
  ['messages', '#ff9e64'],
]
const FALLBACK = ['#2ac3de', '#c0caf5', '#ff757f', '#e0def4']

const colorFor = (name: string, index: number): string =>
  PALETTE.find(([key]) => name.toLowerCase().startsWith(key))?.[1] ?? (FALLBACK[index % FALLBACK.length] as string)

const fmt = (n: number) =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${(n / 1000).toFixed(n >= 10_000 ? 0 : 1)}k` : String(Math.round(n))

const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0)

// Whole cells per value: each edge sits at the running total, so a value too small for a cell costs its neighbours nothing.
const cellsOf = (values: number[], cells: number): number[] => {
  const total = sum(values)
  if (total <= 0) return values.map(() => 0)

  let running = 0
  let previous = 0

  return values.map(v => {
    running += v
    const edge = Math.round((running / total) * cells)
    const mine = edge - previous
    previous = edge

    return mine
  })
}

type Part = { name: string; tokens: number; color: string; isFree: boolean }

type Measure = {
  parts: Part[]
  usedTokens: number
  limit: number
  isCompactOn: boolean
  percent: number
}

// The window as the engine counts it, one part per row of /context, with the free space last.
const measure = (usage: SessionUsage): Measure | null => {
  const breakdown = usage.context.breakdown
  if (!breakdown) return null

  const used = breakdown.categories
    .filter(c => c.kind === 'used' && c.tokens > 0)
    .map((c, i) => ({ name: c.name, tokens: c.tokens, color: colorFor(c.name, i), isFree: false }))
  const usedTokens = sum(used.map(c => c.tokens))
  const threshold = breakdown.isAutoCompactEnabled ? breakdown.autoCompactThreshold : undefined
  const limit = threshold ?? breakdown.rawMaxTokens

  return {
    parts: [...used, { name: 'Free', tokens: Math.max(0, limit - usedTokens), color: FREE_COLOR, isFree: true }],
    usedTokens,
    limit,
    isCompactOn: threshold !== undefined,
    percent: Math.round((usedTokens / limit) * 100),
  }
}

const escapeXml = (text: string) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

const percentColor = (percent: number) => (percent >= 85 ? 'red' : percent >= 60 ? 'yellow' : 'green')

const pct = (m: Measure, tokens: number) => `${Math.round((tokens / m.limit) * 100)}%`
const tipOf = (m: Measure, p: Part) => `${p.name} ${fmt(p.tokens)} · ${pct(m, p.tokens)} of limit`

type Piece = { part: Part; grow: number; source: string }

// The desktop's segments for one reading. The band redraws every few seconds and an unchanged reading is the same
// picture, so each reading's SVG strings are built once, not once per redraw.
const piecesCache = new WeakMap<Measure, Piece[]>()
const piecesOf = (m: Measure): Piece[] => {
  let pieces = piecesCache.get(m)
  if (pieces) return pieces

  const total = sum(m.parts.map(p => p.tokens))
  pieces = m.parts.flatMap(p => {
    const source = `<svg xmlns="http://www.w3.org/2000/svg" width="4000" height="14" viewBox="0 0 100 14" preserveAspectRatio="none"><style>rect:hover{filter:brightness(1.3)}</style><rect width="100" height="14" fill="${p.color}"><title>${escapeXml(tipOf(m, p))}</title></rect></svg>`

    return p.tokens > 0 ? [{ part: p, grow: (p.tokens / total) * 1000, source }] : []
  })
  piecesCache.set(m, pieces)

  return pieces
}

export const register: Register = on => {
  // The last reading, kept so a draw never waits on the engine and never comes up empty.
  let latest: Measure | null = null
  let signature = ''

  on('session.start', async ($, e, next) => {
    // An earlier version drew a pane; one left up by a reload would stay blank.
    await $.ui.close({ id: STALE_PANE })

    // Measures off the draw path and redraws only when a number moved, so the band is not rebuilt for nothing.
    const tick = async () => {
      try {
        const m = measure(await $.session.usage({ breakdown: 'summary' }))
        if (!m) return

        const key = JSON.stringify([m.limit, m.isCompactOn, m.parts.map(p => [p.name, Math.round(p.tokens / 100)])])
        if (key === signature) return

        signature = key
        latest = m
        $.ui.invalidate('ui.render')
      } catch {
        // The last reading stays on screen.
      }
    }
    $.clock.every(POLL_MS, tick)
    await tick()

    return next(e)
  })

  // One row across the band: the engine's own categories, then free space, with the percent and the count at the end.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const m = latest
    if (e.props.hasSurvey || !m) return next(e)

    // Whatever the plugins beneath draw in the band goes under the bar.
    const below = await next(e)
    const hasBelow = Boolean(below) && (below as { type?: string }).type !== 'engine'

    const tip = (p: Part) => tipOf(m, p)
    const percent = `${m.percent}%`
    const amount = ` ${fmt(m.usedTokens)}/${fmt(m.limit)}`

    // The desktop gives a vector frame a width of its own, whatever the band's, so the fill is layout boxes that always
    // stretch to the row, each grown in proportion to its tokens (out of 1000, the engine takes no more than 10000).
    // A frame is drawn at 450px unless told its width, so each is told one wider than any band and clipped to its box.
    // The vector laid in each carries the tooltip and the hover highlight, and paints its own stretch's color, as the frame can turn opaque.
    if (e.surface === 'desktop') {
      const { Box, Svg, Text } = $.ui.resolve(e)
      const pieces = piecesOf(m)

      const bar = (
        <Box flexDirection="row" alignItems="center" columnGap={1} width="100%">
          <Box flexDirection="row" flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
            {pieces.map(piece => (
              <Box width={0} minWidth={0} flexGrow={piece.grow} backgroundColor={piece.part.color} overflow="hidden">
                <Svg source={piece.source} alt={tip(piece.part)} width={4000} height={14} isInteractive />
              </Box>
            ))}
          </Box>
          <Text>
            <Text color={percentColor(m.percent)} bold>
              {percent}
            </Text>
            <Text dimColor>{amount}</Text>
          </Text>
        </Box>
      )

      return hasBelow ? (
        <Box flexDirection="column">
          {bar}
          {below}
        </Box>
      ) : (
        bar
      )
    }

    // The terminal draws it in cells; a stretch's hover reveals a line above the bar, which is the band's bottom row,
    // so the line appearing never moves the bar from under the pointer.
    const { Box, Text } = $.ui.resolve(e)
    const width = Math.max(10, e.props.bodyColumns - percent.length - amount.length - 2)
    const cells = cellsOf(
      m.parts.map(p => p.tokens),
      width,
    )
    const swatch = (p: Part) => (p.isFree ? <Text dimColor>■</Text> : <Text color={p.color}>■</Text>)

    const bar = (
      <Box flexDirection="column">
        {m.parts.map((p, i) =>
          (cells[i] ?? 0) > 0 ? (
            <Box display="none" hover={{ scope: `seg-${i}`, display: 'flex' }}>
              <Text wrap="truncate">
                {swatch(p)}
                <Text> {tip(p)}</Text>
              </Text>
            </Box>
          ) : null,
        )}
        <Box display="none" flexDirection="row" flexWrap="wrap" columnGap={2} hover={{ scope: 'all', display: 'flex' }}>
          {m.parts.map(p => (
            <Text>
              {swatch(p)}
              <Text dimColor>
                {' '}
                {p.name} {fmt(p.tokens)}
              </Text>
            </Text>
          ))}
        </Box>
        <Box>
          {m.parts.map((p, i) =>
            (cells[i] ?? 0) > 0 ? (
              <Text backgroundColor={p.color} hover={{ scope: `seg-${i}` }}>
                {' '.repeat(cells[i] ?? 0)}
              </Text>
            ) : null,
          )}
          <Text color={percentColor(m.percent)} bold hover={{ scope: 'all' }}>
            {` ${percent}`}
          </Text>
          <Text dimColor hover={{ scope: 'all' }}>
            {amount}
          </Text>
        </Box>
      </Box>
    )

    return hasBelow ? (
      <Box flexDirection="column">
        {bar}
        {below}
      </Box>
    ) : (
      bar
    )
  })
}

